create table public.products (id uuid primary key default gen_random_uuid(), store_id uuid not null references public.stores(id) on delete cascade, category_id uuid references public.categories(id) on delete set null, brand_id uuid references public.brands(id) on delete set null, name text not null, slug text not null, description text, status text not null default 'draft' check(status in ('draft','active','archived')), metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(store_id,slug), unique(store_id,id));
create index idx_products_store_status on public.products(store_id,status);
